213	+/// A validated resume of a session with open deferred tool calls.
214	+///
215	+/// The plan holds each open deferral of the session, in log order, with the
216	+/// host decision for it. It also holds the handoff path of the deferring
217	+/// agent and the conversation that each agent on that path saw.
218	+///
219	+/// Only [`ResumePlan::from_events`] makes a plan. A deferral-aware runner
220	+/// makes it and gives it to the agent with
221	+/// [`AgentInput::with_resume_plan`](crate::AgentInput::with_resume_plan).
222	+#[derive(Clone)]
223	+pub struct ResumePlan {
224	+    /// The open deferrals in log order, each with its resolution.
225	+    calls: Vec<PlannedCall>,
226	+    /// The shared handoff path of the open deferrals.
227	+    path: Vec<String>,
228	+    /// `histories[i]` is the conversation of `path[i]`; `[0]` is the snapshot.
229	+    histories: Vec<Vec<crate::Item>>,
230	+    /// `transfers[i]` is the transfer call id from `path[i]` to `path[i + 1]`.
231	+    transfers: Vec<Option<String>>,
232	+    /// The path entry of the agent that receives this plan.
233	+    level: usize,
234	+}
