240	+        f.debug_struct("ResumePlan")
241	+            .field("calls", &self.calls)
242	+            .field("path", &self.path)
243	+            .field(
244	+                "history_lens",
245	+                &self.histories.iter().map(Vec::len).collect::<Vec<_>>(),
246	+            )
247	+            .field("transfers", &self.transfers)
248	+            .field("level", &self.level)
249	+            .finish()
250	+    }
251	+}
252	+
253	+impl ResumePlan {
254	+    /// Validate a resume request against the session log and make a plan.
255	+    ///
256	+    /// `events` is the full session log and `snapshot` is the session
257	+    /// snapshot (a custom session can override the snapshot, so the runner
258	+    /// reads both). `root_agent_name` is the name of the agent that the
259	+    /// runner runs. `input` carries the host resolutions and the new input
260	+    /// messages.
261	+    ///
262	+    /// The checks run in this order: tool items in the input, duplicate
263	+    /// resolutions, no open deferrals, unknown deferral ids, unresolved
264	+    /// deferrals, a session changed after the deferral, a deferred call that
265	+    /// is not in the history, and a handoff path that is too deep.
266	+    ///
267	+    /// A `root_agent_name` that is not the first name of the handoff path is
268	+    /// not an error. The agent then denies every call.
269	+    pub fn from_events(
270	+        events: &[crate::SessionEvent],
271	+        snapshot: &crate::ConversationSnapshot,
272	+        root_agent_name: &str,
273	+        input: &crate::AgentInput,
274	+        max_agent_depth: u32,
275	+    ) -> Result<ResumePlan, InvalidResume> {
276	+        use crate::{Item, SessionEvent};
277	+
278	+        if input
279	+            .messages
280	+            .iter()
281	+            .any(|i| matches!(i, Item::ToolCall { .. } | Item::ToolResult { .. }))
282	+        {
283	+            return Err(InvalidResume::ToolItemsInInput);
284	+        }
285	+
286	+        let resolutions = input.resolutions();
287	+        for (n, (id, _)) in resolutions.iter().enumerate() {
288	+            if resolutions[..n].iter().any(|(other, _)| other == id) {
289	+                return Err(InvalidResume::DuplicateResolution {
290	+                    deferral_id: id.clone(),
291	+                });
292	+            }
293	+        }
294	+
295	+        let open = open_deferral_positions(events);
296	+        let Some(&(first, _)) = open.first() else {
297	+            return Err(InvalidResume::NoOpenDeferrals);
298	+        };
299	+
300	+        for (id, _) in resolutions {
301	+            if !open.iter().any(|(_, c)| c.deferral_id() == id) {
302	+                return Err(InvalidResume::UnknownDeferral {
303	+                    deferral_id: id.clone(),
304	+                });
305	+            }
306	+        }
307	+
308	+        let missing: Vec<String> = open
309	+            .iter()
310	+            .filter(|(_, c)| !resolutions.iter().any(|(id, _)| id == c.deferral_id()))
311	+            .map(|(_, c)| c.deferral_id().to_owned())
312	+            .collect();
313	+        if !missing.is_empty() {
314	+            return Err(InvalidResume::UnresolvedDeferrals { missing });
315	+        }
316	+
317	+        if events[first + 1..].iter().any(|e| {
318	+            matches!(
319	+                e,
320	+                SessionEvent::UserMessage { .. }
321	+                    | SessionEvent::AssistantMessage { .. }
322	+                    | SessionEvent::ToolCalled { .. }
323	+            )
324	+        }) {
325	+            return Err(InvalidResume::SessionModified);
326	+        }
327	+        let path = open[0].1.handoff_path().to_vec();
328	+        if path.is_empty() || open.iter().any(|(_, c)| c.handoff_path() != path) {
329	+            return Err(InvalidResume::SessionModified);
330	+        }
331	+        let handoffs = handoff_indices(events, &path, first)?;
332	+
333	+        for (_, call) in &open {
334	+            let messages = &snapshot.messages;
335	+            let found = messages.iter().rposition(
336	+                |i| matches!(i, Item::ToolCall { call_id, .. } if call_id == call.call_id()),
337	+            );
338	+            let valid = found.is_some_and(|p| {
339	+                let same_name =
340	+                    matches!(&messages[p], Item::ToolCall { name, .. } if name == call.tool());
341	+                let answered = messages[p + 1..].iter().any(
342	+                    |i| matches!(i, Item::ToolResult { call_id, .. } if call_id == call.call_id()),
343	+                );
344	+                same_name && !answered
345	+            });
346	+            if !valid {
347	+                return Err(InvalidResume::CallNotInHistory {
348	+                    call_id: call.call_id().to_owned(),
349	+                });
350	+            }
351	+        }
352	+
353	+        if path.len() > max_agent_depth as usize + 1 {
354	+            return Err(InvalidResume::PathTooDeep {
355	+                len: path.len(),
356	+                max_agent_depth,
357	+            });
358	+        }
359	+
360	+        let mut histories = vec![snapshot.messages.clone()];
361	+        if root_agent_name == path[0] {
362	+            for level in 1..path.len() {
363	+                histories.push(agent_view(events, &handoffs, level, events.len()));
364	+            }
365	+        }
366	+        let transfers = (1..path.len())
367	+            .map(|level| transfer_call_before(events, handoffs[level]))
368	+            .collect();
369	+
370	+        let calls = open
371	+            .into_iter()
372	+            .map(|(_, pending)| {
373	+                let resolution = resolutions
374	+                    .iter()
375	+                    .find(|(id, _)| id == pending.deferral_id())
376	+                    .map(|(_, r)| r.clone())
377	+                    .expect("every open deferral has a resolution");
378	+                PlannedCall {
379	+                    pending,
380	+                    resolution,
381	+                }
382	+            })
383	+            .collect();
384	+
385	+        Ok(ResumePlan {
386	+            calls,
387	+            path,
388	+            histories,
389	+            transfers,
390	+            level: 0,
391	+        })
392	+    }
393	+
394	+    /// The open deferrals in log order, each with its resolution.
395	+    #[cfg_attr(not(test), expect(dead_code, reason = "used from Task 8a"))]
396	+    pub(crate) fn calls(&self) -> &[PlannedCall] {
397	+        &self.calls
398	+    }
