417	+        self.path.get(self.level + 1).map(String::as_str)
418	+    }
419	+
420	+    /// The transfer call id from the receiving agent to [`Self::next_agent`].
421	+    #[cfg_attr(not(test), expect(dead_code, reason = "used from Task 8b"))]
422	+    pub(crate) fn transfer_call_to_next(&self) -> Option<&str> {
423	+        self.transfers.get(self.level)?.as_deref()
424	+    }
425	+
426	+    /// The conversation that the receiving agent saw when the call was
427	+    /// deferred. Empty when the plan has no history for this level (a
428	+    /// renamed root agent).
429	+    #[cfg_attr(not(test), expect(dead_code, reason = "used from Task 8a"))]
430	+    pub(crate) fn history(&self) -> &[crate::Item] {
431	+        self.histories.get(self.level).map_or(&[], Vec::as_slice)
432	+    }
433	+
434	+    /// The plan for the next agent on the handoff path.
435	+    #[cfg_attr(not(test), expect(dead_code, reason = "used from Task 8b"))]
436	+    pub(crate) fn descend(&self) -> ResumePlan {
437	+        ResumePlan {
438	+            level: self.level + 1,
439	+            ..self.clone()
440	+        }
441	+    }
442	+
443	+    /// A copy of this plan where every resolution is `Denied { reason }`.
444	+    #[cfg_attr(not(test), expect(dead_code, reason = "used from Task 8b"))]
445	+    pub(crate) fn with_all_denied(&self, reason: &str) -> ResumePlan {
446	+        let mut plan = self.clone();
447	+        for call in &mut plan.calls {
448	+            call.resolution = ToolResolution::Denied {
449	+                reason: reason.to_owned(),
450	+            };
451	+        }
452	+        plan
453	+    }
454	+}
455	+
456	+/// The log index `k_i` of the `HandoffOccurred` event into `path[i]` for each
457	+/// level `i` (`k_0 = 0`), all before `deferred_at`.
458	+///
459	+/// The search runs from the deepest level back to the root: `k_i` is the last
460	+/// matching handoff before `k_{i+1}`. So a path that visits an agent two times
461	+/// finds the handoffs of the latest chain.
462	+fn handoff_indices(
463	+    events: &[crate::SessionEvent],
464	+    path: &[String],
465	+    deferred_at: usize,
466	+) -> Result<Vec<usize>, InvalidResume> {
467	+    use crate::SessionEvent;
468	+    let mut indices = vec![0; path.len()];
469	+    let mut upper = deferred_at;
470	+    for level in (1..path.len()).rev() {
471	+        let k = events[..upper]
472	+            .iter()
473	+            .rposition(|e| {
474	+                matches!(e, SessionEvent::HandoffOccurred { from, to, .. }
475	+                    if *from == path[level - 1] && *to == path[level])
476	+            })
477	+            .ok_or(InvalidResume::SessionModified)?;
478	+        indices[level] = k;
479	+        upper = k;
480	+    }
481	+    Ok(indices)
482	+}
483	+
484	+/// `view(level, end)`: the conversation of `path[level]` over `events[..end]`.
485	+///
486	+/// `view(0, end)` is the projection of `events[..end]`. A child view threads
487	+/// the parent view at its handoff (no tool items, plus a transfer note) and
488	+/// then adds the projection of the events after the handoff.
489	+fn agent_view(
490	+    events: &[crate::SessionEvent],
491	+    handoffs: &[usize],
492	+    level: usize,
493	+    end: usize,
494	+) -> Vec<crate::Item> {
495	+    if level == 0 {
496	+        return crate::project(&events[..end]).messages;
497	+    }
498	+    let k = handoffs[level];
499	+    let mut view =
500	+        crate::loop_state::thread_handoff_transcript(&agent_view(events, handoffs, level - 1, k));
501	+    view.extend(crate::project(&events[k + 1..end]).messages);
502	+    view
503	+}
504	+
505	+/// The transfer call id of the handoff at `handoff_at`.
506	+///
507	+/// The loop records the transfer `ToolCalled` events of a handoff response
508	+/// directly before the `HandoffOccurred` event, with the assistant text of
509	+/// that response. The first transfer call names the target. This finds the
510	+/// call by its position, not by its tool name, because a handoff can use a
511	+/// custom tool name.
512	+fn transfer_call_before(events: &[crate::SessionEvent], handoff_at: usize) -> Option<String> {
513	+    use crate::SessionEvent;
514	+    events[..handoff_at]
515	+        .iter()
516	+        .rev()
517	+        .take_while(|e| {
518	+            matches!(
519	+                e,
520	+                SessionEvent::ToolCalled { .. } | SessionEvent::AssistantMessage { .. }
521	+            )
522	+        })
523	+        .filter_map(|e| match e {
524	+            SessionEvent::ToolCalled { call_id, .. } => Some(call_id.clone()),
525	+            _ => None,
526	+        })
527	+        .last()
528	+}
