-                name.clone(),
-                args.clone(),
-                prompt.clone(),
-                handoff_path.clone(),
+            open.push((
+                i,
+                PendingToolCall::new(
+                    deferral_id.clone(),
+                    call_id.clone(),
+                    name.clone(),
+                    args.clone(),
+                    prompt.clone(),
+                    handoff_path.clone(),
+                ),
