+/// call by its position, not by its tool name, because a handoff can use a
+/// custom tool name.
+fn transfer_call_before(events: &[crate::SessionEvent], handoff_at: usize) -> Option<String> {
+    use crate::SessionEvent;
+    events[..handoff_at]
