+            matches!(
+                e,
+                SessionEvent::ToolCalled { .. } | SessionEvent::AssistantMessage { .. }
+            )
+        })
+        .filter_map(|e| match e {
+            SessionEvent::ToolCalled { call_id, .. } => Some(call_id.clone()),
+            _ => None,
+        })
+        .last()
